const end = new Date();
const start = new Date(end.getTime() - 7 * 24 * 60 * 60 * 1000);
const fmt = (d) => d.toISOString().slice(0, 10);
return [{ json: { startDate: fmt(start), endDate: fmt(end) } }];

const fs = require('fs');
const path = require('path');
const PROJECT_ROOT = $env.INVISIBLE_WHY_ROOT || '/data/youtube-invisible-why';
const range = $('Compute Date Range').item.json;
const report = $json;

const snapshotPath = path.join(PROJECT_ROOT, 'analytics', range.endDate + '-snapshot.json');
fs.mkdirSync(path.dirname(snapshotPath), { recursive: true });
fs.writeFileSync(snapshotPath, JSON.stringify(report, null, 2));

const rows = report.rows || [];
const totals = rows.reduce((acc, r) => {
  const [day, views, minutesWatched, avgDuration, avgPct, subsGained, likes, comments] = r;
  acc.views += views || 0;
  acc.minutesWatched += minutesWatched || 0;
  acc.subsGained += subsGained || 0;
  acc.likes += likes || 0;
  acc.comments += comments || 0;
  return acc;
}, { views: 0, minutesWatched: 0, subsGained: 0, likes: 0, comments: 0 });

const csvPath = path.join(PROJECT_ROOT, 'analytics', 'weekly-summary.csv');
const header = 'week_ending,views,minutes_watched,subscribers_gained,likes,comments\n';
if (!fs.existsSync(csvPath)) fs.writeFileSync(csvPath, header);
const line = [range.endDate, totals.views, totals.minutesWatched, totals.subsGained, totals.likes, totals.comments].join(',') + '\n';
fs.appendFileSync(csvPath, line);

return [{ json: { ...totals, weekEnding: range.endDate } }];
